    public static void main(String[] args)
    {
        Scanner s1=new Scanner(System.in);
        int n=s1.nextInt();
        int k=s1.nextInt();
        int time=240-k;
        int ans=0;
        int start=1;
        int end=240;
        while(start<=end)
        {   
            int middle=(start+end)/2;
            int sum= 5 * (middle) *(middle+1) / 2;
            if (time>=sum)
            {
                //System.out.println(sum);
                start=middle+1;
                ans=start;
            }
            else
            {
                end=middle-1;
            }
        }
        if (ans>n)
            ans=n+1;
        if (ans<=0)
            ans=1;
        System.out.println(ans-1);
    }

}
